<script setup lang="ts">
import{computed,ref,onMounted,onBeforeUnmount}from'vue';import{useEngine}from'../stores/engine';import{api,diagnostics,nativeAndroid,chooseAndroidEngine,openBackgroundSettings,copyText}from'../services/api';import{confirmAction}from'../services/confirm';import Icon from'../components/Icon.vue';import LicensePanel from'../components/LicensePanel.vue';import EngineUpdates from'../components/EngineUpdates.vue';
const e=useEngine();const error=ref(''),result=ref(''),logs=ref(''),query=ref(''),level=ref('all'),upload=ref<File>(),checking=ref(false),logBusy=ref(false);const reduceMotion=ref(localStorage.getItem('air2mi-reduce-motion')==='1');const toneBusy=computed(()=>['connecting','playing','stopping'].includes(e.tone?.phase||''));function motion(){localStorage.setItem('air2mi-reduce-motion',reduceMotion.value?'1':'0');document.documentElement.dataset.reduceMotion=String(reduceMotion.value)}motion();
function phaseLabel(value?:string){return({running:'运行中',starting:'启动中',stopping:'停止中',stopped:'已停止',failed:'异常'} as Record<string,string>)[value||'']||'待查询'}
const background=ref<any>();async function readBackground(){if(nativeAndroid)try{background.value=await api('/background')}catch(err){error.value=String(err)}}
function imported(event:Event){result.value=(event as CustomEvent).detail?.restart_required?'组件已暂存。当前内核继续运行；请停止内核，在系统应用设置中完全停止 Air2Mi 后重新打开，以加载新版。':'内核组件已导入，可启动。';void e.refresh()}function importError(event:Event){error.value=(event as CustomEvent).detail||'组件导入失败'}
onMounted(()=>{window.addEventListener('air2mi-engine-updated',imported);window.addEventListener('air2mi-import-error',importError);void readBackground()});onBeforeUnmount(()=>{window.removeEventListener('air2mi-engine-updated',imported);window.removeEventListener('air2mi-import-error',importError)});
async function action(name:string){if(name!=='start'&&!await confirmAction(name==='stop'?'停止内核':'重启内核','当前投放会断开，设备身份和已保存的配置不会改变。'))return;try{await e.run(()=>api('/lifecycle/'+name,'POST'));error.value=''}catch(err){error.value=String(err)}}
async function doctor(){checking.value=true;try{result.value=(await api('/doctor','POST')).output;error.value=''}catch(err){error.value=String(err)}finally{checking.value=false}}
async function readLogs(){logBusy.value=true;try{logs.value=(await api('/logs?q='+encodeURIComponent(query.value)+'&level='+level.value)).text;error.value=''}catch(err){error.value=String(err)}finally{logBusy.value=false}}
async function install(){if(nativeAndroid){chooseAndroidEngine();return}if(!upload.value||!await confirmAction(e.snapshot?.engine_installed?'更新内核':'安装内核','组件将校验签名、平台及 API 版本。更新前停止旧内核并保留配置与身份，失败时回滚内核文件。'))return;try{await e.run(()=>api('/update','POST',upload.value));result.value='内核组件安装完成。可在运行管理中启动。';error.value=''}catch(err){error.value=String(err)}}
function pick(event:Event){upload.value=(event.target as HTMLInputElement).files?.[0]}async function copy(value:string){try{await copyText(value)}catch(err){error.value='复制失败：'+String(err)}}async function exportData(){try{await diagnostics()}catch(err){error.value=String(err)}}
</script>
<template><header class="page-header"><div><h1>设置</h1><p class="page-description">管理运行、查看诊断，保持应用与内核各自更新。</p></div></header><p v-if="error" class="notice error" role="alert"><Icon name="warning"/><span>{{error}}</span><button class="icon-button" aria-label="关闭错误" @click="error=''"><Icon name="close" :size="16"/></button></p><div class="settings-pair"><section class="panel"><div class="panel-heading"><div class="section-icon-title"><span class="summary-icon"><Icon name="river"/></span><div><h2>Engine 运行管理</h2><p>{{e.snapshot?.engine_installed?'本应用独立管理的音频内核':'尚未安装内核，管理界面已就绪'}}</p></div></div><span class="badge" :class="e.snapshot?.engine_running?'teal':'neutral'">{{toneBusy?'测试音模式':e.snapshot?.engine_running?'已连接':e.snapshot?.engine_installed?'已停止':'待安装'}}</span></div><div class="version-row"><div><small>Engine</small><b>{{e.snapshot?.engine_manifest.kernel_version||'未安装'}}</b></div><div><small>API</small><b>{{e.snapshot?.engine_manifest.api_version||'待连接'}}</b></div><div><small>Air2Mi App</small><b>{{e.snapshot?.app_version||'开发版'}}</b></div></div><div class="actions"><button :disabled="e.busy||!e.snapshot?.engine_installed||e.snapshot?.engine_running||toneBusy" @click="action('start')"><Icon name="play" :size="17"/>启动</button><button class="secondary" :disabled="e.busy||!e.snapshot?.engine_running||toneBusy" @click="action('restart')"><Icon name="refresh" :size="17"/>重启</button><button class="secondary" :disabled="e.busy||!e.snapshot?.engine_running||toneBusy" @click="action('stop')"><Icon name="stop" :size="17"/>停止</button><button class="text" :disabled="checking||!e.snapshot?.engine_installed||toneBusy" @click="doctor"><Icon name="shield" :size="17"/>{{checking?'自检中…':'运行自检'}}</button></div><p class="field-help">关闭管理窗口不会停止音频。仅管理本应用的数据和内核进程。</p></section><EngineUpdates component="engine">
  <template #offline="{ updating }">
    <h3>离线导入</h3>
    <template v-if="nativeAndroid"><button class="secondary" :disabled="updating||e.busy||toneBusy" @click="chooseAndroidEngine"><Icon name="upload" :size="18"/>导入 Android 内核 ZIP</button><p class="field-help">使用可信的 Android ARM64 组件 ZIP。若提示需要重启，请完全退出后重新打开应用。</p></template><template v-else><label class="upload-area"><Icon name="upload" :size="28"/><b>{{upload?.name||'选择内核组件 ZIP'}}</b><span>受信任的 Linux Engine 包 · API v1</span><input type="file" accept=".zip" :disabled="updating||e.busy||toneBusy" aria-label="选择内核组件 ZIP" @change="pick"/></label><button :disabled="!upload||updating||e.busy||toneBusy" @click="install"><Icon name="shield" :size="17"/>{{e.snapshot?.engine_installed?'校验并更新':'校验并安装'}}</button></template>
  </template>
</EngineUpdates></div><section v-if="nativeAndroid" class="panel"><div class="panel-heading"><div><h2>后台运行</h2><p>音频由独立前台服务维持，关闭页面或划走最近任务不会主动停止内核。</p></div><button class="secondary compact" @click="readBackground">刷新状态</button></div><dl class="settings-facts"><dt>服务</dt><dd>{{phaseLabel(e.snapshot?.background?.service_phase||background?.service_phase)}}</dd><dt>常驻通知</dt><dd>{{background?.notifications_allowed?'已允许':'未允许'}}</dd><dt>电池优化</dt><dd>{{background?.battery_unrestricted?'已取消优化':'由系统管理'}}</dd></dl><div class="actions"><button class="secondary" @click="openBackgroundSettings('notifications')">通知设置</button><button class="secondary" @click="openBackgroundSettings()">电池优化设置</button></div><p class="field-help">请在系统中允许通知和后台运行；不同厂商的省电策略可能仍会回收服务。系统“强行停止”后需重新打开应用。通知中的停止按钮会停止内核并释放运行锁。</p></section><LicensePanel/>
<EngineUpdates component="app"/><section class="panel logs-panel"><div class="panel-heading"><div class="section-icon-title"><span class="summary-icon neutral"><Icon name="file"/></span><div><h2>日志与诊断</h2><p>按需读取本应用日志，敏感认证字段自动隐藏。</p></div></div><button class="secondary compact" @click="exportData"><Icon name="download" :size="16"/>导出诊断</button></div><form class="log-toolbar" @submit.prevent="readLogs"><div class="search-input"><Icon name="search" :size="17"/><input v-model="query" aria-label="搜索日志" placeholder="搜索日志内容"/></div><select v-model="level" aria-label="日志等级"><option value="all">全部等级</option><option value="error">Error</option><option value="warning">Warning</option><option value="info">Info</option></select><button class="secondary" :disabled="logBusy">{{logBusy?'读取中…':'读取日志'}}</button></form><div class="log-output"><pre v-if="logs">{{logs}}</pre><div v-else class="small-empty">按需读取日志，不持续刷屏。</div></div><button v-if="logs" class="text" @click="copy(logs)"><Icon name="copy" :size="16"/>复制日志</button></section><section v-if="result" class="panel"><div class="panel-heading"><h2>操作结果</h2><button class="icon-button" aria-label="复制结果" @click="copy(result)"><Icon name="copy" :size="17"/></button></div><pre>{{result}}</pre></section><details class="panel advanced-panel"><summary><span><Icon name="network" :size="18"/>网络与高级诊断</span><Icon name="chevron" :size="16"/></summary><dl class="settings-facts"><dt>绑定地址</dt><dd>{{e.snapshot?.bind||'未报告'}}</dd><dt>数据面</dt><dd>{{e.snapshot?.state?.kernel?.state||'未运行'}}</dd><template v-if="nativeAndroid"><dt>Android API</dt><dd>{{e.snapshot?.environment?.android_api||'未知'}}</dd><dt>局域网发现</dt><dd>Android NSD / Wi-Fi 组播</dd></template><template v-else><dt>glibc</dt><dd>{{e.snapshot?.environment?.glibc||'未知'}}</dd><dt>D-Bus Socket</dt><dd>{{e.snapshot?.environment?.dbus_socket?'已检测到':'未检测到'}}</dd><dt>Avahi Socket</dt><dd>{{e.snapshot?.environment?.avahi_socket?'已检测到':'未检测到'}}</dd></template><dt>内核构建</dt><dd>{{e.snapshot?.engine_manifest.package_version||'未安装'}}</dd><dt>源码提交</dt><dd class="mono">{{e.snapshot?.engine_manifest.source_commit||'未安装'}}</dd></dl><p class="field-help">Socket 存在不等同于服务完整健康；编码自检和真实音箱测试分别验证。独立实时音量、多目标关联和详细队列观测仍以 Engine 已开放能力为准。</p></details><section class="panel"><h2>应用偏好</h2><label class="toggle-row"><span><b>减少界面动效</b><small>仅影响界面，不改变音频处理</small></span><input type="checkbox" role="switch" v-model="reduceMotion" @change="motion"/></label></section><footer class="about-footer"><span class="brand-symbol small"><Icon name="river" :size="23"/></span><div><b>Air2Mi</b><p>App {{e.snapshot?.app_version||'开发版'}} · {{nativeAndroid?'Android ARM64': 'fnOS x64'}}</p><small>应用源码 MIT。独立 Engine 及其依赖遵循各自许可。</small></div></footer></template>
